# Source for usecase_questions_v3.json (generated by build_v3.py). One entry per use case.
# Row tuples (one per ORIGINAL question, plus added ones):
#   (qid, 'keep'|'fix'|'rewrite', weight, new_text, why, reason[, show_if])
#   (qid, 'remove', None, None, None, reason)
#   (qid, 'merge', target, None, None, reason)   target = another qid in this use case, 'gate:G_ACT' etc., or 'mh:m2' etc.
#   (qid, 'split', [w1, w2], [text1, text2], [why1, why2], reason)
#   ('+area:owner', 'add', weight, text, why, reason[, show_if])   new question
#   keep = same meaning, wording only polished; fix = meaning corrected or narrowed; rewrite = replaced by a use-case-specific question
#   show_if = 'gateid=optionkey' (shown only then)
# Generic topics (named owner, budget, system connection in general, staff training, fallback) are must-haves; use-case questions cover only what is specific to the use case.
# areas: pe People, sk Skills, fi Financial investment, te Technology infrastructure, da Data, or Organisation & controls
# owners: GM, OWN, FIN, IT, VEN, HR, DH, STAFF ; weights: B blocker, I important, N nice-to-have
# gates: 'AUTO_GUEST' / 'AUTO_ACT' / 'AUTO_PEOPLE' = not asked, effect of guests / acts-by-itself applied automatically (use case is always that way)
# gates: library ids ('G_ACT','G_GUEST','G_PEOPLE','G_LINK','G_PAID') or custom gates built with CG(); max 2 per use case
UC = {}
def U(uid, gates, rows, sens=False, note='', title=None):
    assert uid not in UC, uid
    UC[uid] = dict(gates=gates, rows=rows, sens=sens, note=note, title=title)
def CG(gid, text, options):
    return dict(id=gid, text=text, options=[dict(key=k, label=l, effects=e) for k, l, e in options])
FLAG = {'sensitive_flag': True}
def DK(action): return {'cap_almost': True, 'action': action}
def YESNO(gid, text, yes_label, no_label, yes_eff, dk_action, no_eff=None):
    return CG(gid, text, [('yes', yes_label, yes_eff), ('no', no_label, no_eff or {}), ('dk', "Don't know yet", DK(dk_action))])
def PERSONAL(gid, text, dk_action):
    return YESNO(gid, text, 'Yes', 'No', dict(FLAG), dk_action)
